import{_ as t,o,c as r,a3 as d}from"./chunks/framework.CVt6dz2a.js";const q=JSON.parse('{"title":"EP.25 显卡打了个嗝：上下文丢失急救","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.25-context-loss-recovery.md","filePath":"comics/EP.25-context-loss-recovery.md","lastUpdated":1793881879000}'),a={name:"comics/EP.25-context-loss-recovery.md"};function l(c,e,i,n,s,u){return o(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="ep-25-显卡打了个嗝-上下文丢失急救" tabindex="-1">EP.25 显卡打了个嗝：上下文丢失急救 <a class="header-anchor" href="#ep-25-显卡打了个嗝-上下文丢失急救" aria-label="Permalink to &quot;EP.25 显卡打了个嗝：上下文丢失急救&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/25-monitoring-resilience/basics">25.1 基础入门：WebGL 上下文丢失与自愈</a> 延伸阅读：<a href="./../guide/25-monitoring-resilience/advanced">25.2 进阶应用：容错分级与监控上报体系</a> · <a href="./../guide/25-monitoring-resilience/practice">25.3 实战案例：给 3D 应用装上&quot;黑匣子&quot;</a> 动手演示：<a href="./../public/demos/monitoring/context-loss-lab.html">context-loss-lab 上下文丢失急救台</a> · <a href="./../public/demos/monitoring/telemetry-pipeline.html">telemetry-pipeline 遥测管道</a> · <a href="./../public/demos/monitoring/resilience-ladder.html">resilience-ladder 黑匣子时间线</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>园区大屏突然黑屏，标签君在现场怎么都复现不了，像素酱一句&quot;刷新又好了&quot;把问题变得更玄。</td></tr><tr><td>② 揭秘</td><td>码叔把 WebGL 上下文比作 GPU 的办公桌：桌子被收走，JS 对象还在，但所有显存句柄都失效了。</td></tr><tr><td>③ 实证</td><td>两个事件接上，<code>preventDefault()</code> 报名恢复，<code>rebuildWorld()</code> 整组重建，状态机从 lost 走回 running。</td></tr><tr><td>④ 结案</td><td>坑点清单：只阻止不重建、恢复直接回 L0、不落快照。码叔总结：状态机管生死，黑匣子管证据。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-黑屏不是-js-报错-上下文丢失是静默的" tabindex="-1">① 黑屏不是 JS 报错：上下文丢失是静默的 <a class="header-anchor" href="#_1-黑屏不是-js-报错-上下文丢失是静默的" aria-label="Permalink to &quot;① 黑屏不是 JS 报错：上下文丢失是静默的&quot;">​</a></h3><ul><li>控制台不报红、<code>try/catch</code> 抓不到、<code>renderer.render()</code> 也不抛错，只是画布不再刷新；</li><li>用户看到的是整块黑屏，页面其它模块（图表、告警列表）往往还正常；</li><li>&quot;刷新一下又好了&quot;是最典型的线索：刷新等于重新申请上下文，但现场也被一起清掉了。</li></ul><h3 id="_2-两个事件-lost-是通知-restored-是机会" tabindex="-1">② 两个事件：lost 是通知，restored 是机会 <a class="header-anchor" href="#_2-两个事件-lost-是通知-restored-是机会" aria-label="Permalink to &quot;② 两个事件：lost 是通知，restored 是机会&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事件</th><th>含义</th><th>必须做的事</th></tr></thead><tbody><tr><td><code>webglcontextlost</code></td><td>浏览器/驱动收走了上下文</td><td>同步调用 <code>preventDefault()</code>，停循环、落快照、切兜底</td></tr><tr><td><code>webglcontextrestored</code></td><td>浏览器把上下文还回来了</td><td>重建全部 GPU 资源，再重启渲染循环</td></tr></tbody></table><p><code>preventDefault()</code> 只是&quot;我愿意恢复&quot;的报名，不是&quot;一定会恢复&quot;的保证。restored 可能几毫秒后来，也可能永远不来；所以既要接事件，也要有超时兜底。Three.js 内部已经替我们阻止了默认行为，但<strong>重建资源的责任始终在业务侧</strong>。</p><h3 id="_3-恢复要用-重建函数-不要打补丁" tabindex="-1">③ 恢复要用&quot;重建函数&quot;，不要打补丁 <a class="header-anchor" href="#_3-恢复要用-重建函数-不要打补丁" aria-label="Permalink to &quot;③ 恢复要用&quot;重建函数&quot;，不要打补丁&quot;">​</a></h3><p>上下文一丢，geometry、material、texture、program、render target 的 GPU 副本全部作废。补丁式修复会漏掉后处理、GPGPU、环境贴图这些&quot;业务自己持有&quot;的资源，表现就是场景回来了但泛光没了、粒子不动了、贴图发黑。</p><p>正确纪律是两段式：<code>disposeWorld()</code> 只负责销毁，<code>buildWorld()</code> 只负责创建，中间用一个 <code>rebuildWorld()</code> 串起来。初始化、上下文恢复、热重载、切场景全走同一个入口，天然幂等，也天然可测试。</p><h3 id="_4-状态机-黑匣子-让自愈和自证同时成立" tabindex="-1">④ 状态机 + 黑匣子：让自愈和自证同时成立 <a class="header-anchor" href="#_4-状态机-黑匣子-让自愈和自证同时成立" aria-label="Permalink to &quot;④ 状态机 + 黑匣子：让自愈和自证同时成立&quot;">​</a></h3><p>容错逻辑一旦散落在 resize、事件回调、定时器里，就会互相踩脚。把它们收敛成五个状态：<code>healthy</code>、<code>degraded</code>、<code>suspended</code>、<code>recovering</code>、<code>failed</code>，每次迁移都写事件日志。</p><p>同时用环形缓冲保留最近 30 秒帧时间，挂起/失败时把 <code>renderer.info</code>、当前档位、最近事件一起落成快照。恢复时回到崩溃前的档位，而不是直接回 L0——刚出过事的设备，经不起全画质的二次冲击。</p><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：调了 <code>preventDefault()</code> 还是回不来？</strong> 它只代表&quot;有资格恢复&quot;，显存耗尽、GPU 进程崩溃、驱动不可恢复都会让 restored 永远不来；要加恢复超时和静态兜底。</li><li><strong>Q：恢复后贴图发黑、泛光消失？</strong> 旧纹理与 render target 的 GPU 副本已经失效。不要复用 <code>dispose()</code> 过的对象，整组重建最省心。</li><li><strong>Q：恢复时直接回 L0 行不行？</strong> 不行。回到崩溃前档位先站稳，再按迟滞规则逐级升回，否则很容易二次崩溃。</li><li><strong>Q：用户说黑屏但本地复现不了？</strong> 先查快照里的 <code>state</code>、<code>frame.p95</code>、<code>renderer.info</code>，再对齐 GPU、DPR、是否切过后台；最后用 <code>WEBGL_lose_context</code> 主动触发一次，验证恢复路径本身是否通。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>为什么 <code>webglcontextlost</code> 里的 <code>preventDefault()</code> 必须同步调用？Three.js 已经调用了它，业务侧还需要做什么？</li><li>上下文恢复后，哪些资源必须重建？为什么&quot;补丁式修复&quot;容易漏掉后处理与粒子系统？</li><li>黑匣子的环形缓冲为什么选 30 秒？快照里为什么要带 <code>renderer.info</code> 和最近事件？</li></ol><details><summary>答案</summary><ol><li>规范规定：如果 lost 事件的默认行为没有被阻止，浏览器会认为页面不打算恢复，上下文永久丢失。<code>preventDefault()</code> 必须写在事件回调的第一行，不能 <code>setTimeout</code> 之后再补。Three.js 的 <code>WebGLRenderer</code> 内部已经阻止了默认行为，但那只解决&quot;有没有资格恢复&quot;，恢复之后 geometry、material、texture、program、render target 的重建仍然要业务侧自己做。</li><li>所有 GPU 侧对象都要重建：几何体缓冲、材质与着色器程序、纹理、render target/FBO，以及业务自己持有的 VAO、GPGPU ping-pong 缓冲、后处理链。补丁式修复只盯着&quot;看得见的模型&quot;，很容易漏掉 <code>EffectComposer</code> 内部的 render target 和粒子系统的浮点纹理，于是出现&quot;场景回来了但泛光没了、粒子不动了&quot;的半恢复状态。整组 <code>disposeWorld()</code> + <code>buildWorld()</code> 可以一次性覆盖。</li><li>30 秒足够覆盖&quot;劣化 → 触发 → 崩溃&quot;的完整过程，1800 个 <code>Float32</code> 只占约 7KB，内存恒定且永远保留最近现场。快照带 <code>renderer.info</code> 是为了回答&quot;卡在哪&quot;：draw call、三角形数、几何体/纹理数量能区分合批失败、LOD 失效和资源泄漏；带最近事件是为了回答&quot;为什么卡&quot;，把用户操作、降级、上下文事件和帧时间对齐成一条时间线。</li></ol></details>',21)])])}const p=t(a,[["render",l]]);export{q as __pageData,p as default};
